(function (global) {
  'use strict';

  const DS = (global.DualSub = global.DualSub || {});
  const { EN, TR } = DS.constants;

  // YouTube keeps its caption tracks on the <video> element as ordinary
  // TextTracks. The generic reader can already see those, so this adaptor only
  // exists to do the four things YouTube specifically needs:
  //
  //   1. wait for the track list, which appears after the player boots
  //   2. prefer a human-authored track over the auto-generated one when a video
  //      ships both (the ASR track is real, just rougher)
  //   3. strip the karaoke/positioning markup YouTube puts inside cue text
  //   4. follow cue changes, because YouTube replaces cue objects as playback
  //      advances instead of reusing one list

  const HOSTS = /(^|\.)youtube\.com$|(^|\.)youtu\.be$/;

  function isYouTube() {
    try {
      return HOSTS.test(String(global.location && global.location.hostname || ''));
    } catch (error) {
      return false;
    }
  }

  function tracksOf(video) {
    if (!video || !video.textTracks) {
      return [];
    }

    return Array.from(video.textTracks).filter((track) =>
      track && (track.kind === 'subtitles' || track.kind === 'captions'));
  }

  // WebVTT cues can carry inline markup: karaoke timestamps, <c> spans for
  // word highlighting, and positioning tags such as {\an8}. None of it belongs
  // in the reading line, and the karaoke timestamps would otherwise be read as
  // part of the sentence.
  function cleanText(text) {
    return String(text == null ? '' : text)
      .replace(/<[^>]*>/g, '')
      .replace(/\{\\[^}]*\}/g, '')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&amp;/gi, '&')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function cuesOf(track) {
    const out = [];
    if (!track || !track.cues) {
      return out;
    }

    for (let i = 0; i < track.cues.length; i += 1) {
      const cue = track.cues[i];
      if (!cue) {
        continue;
      }
      const text = cleanText(cue.text);
      if (!text) {
        continue;
      }
      out.push({
        start: Number(cue.startTime),
        end: Number(cue.endTime),
        text: text
      });
    }

    return out;
  }

  function isAutoGenerated(track) {
    const label = String(track && track.label || '');
    return /auto[- ]?generated|otomatik/i.test(label) ||
      String(track && track.kind || '') === 'captions' && /auto/i.test(label);
  }

  // Declared language first, then the label, then the words themselves. A track
  // that is unmistakably a different language is dropped instead of being
  // filed under English.
  function kindOf(track, cues) {
    const lang = String(track && track.language || '').trim().toLowerCase();
    const short = lang.split('-')[0];

    if (['en', 'eng'].includes(short)) {
      return EN;
    }
    if (['tr', 'tur'].includes(short)) {
      return TR;
    }

    for (const name of [lang, String(track && track.label || '')]) {
      if (!name) {
        continue;
      }
      const verdict = DS.langDetect.classify(name, '');
      if (verdict.confidence === 'certain' && verdict.lang) {
        return verdict.lang === 'en' ? EN : TR;
      }
      if (verdict.confidence === 'foreign') {
        return null;
      }
    }

    const sample = (cues || []).slice(0, 6).map((cue) => cue.text).join(' ');
    const verdict = DS.langDetect.classify('', sample);
    if (verdict.confidence === 'foreign') {
      return null;
    }
    return verdict.lang ? (verdict.lang === 'en' ? EN : TR) : null;
  }

  // Some tracks populate their cue list lazily. Forcing the track hidden both
  // materialises the cues and keeps YouTube's own rendering out of the way.
  async function ensureCues(track) {
    let cues = cuesOf(track);
    if (cues.length) {
      return cues;
    }

    try {
      track.mode = 'hidden';
    } catch (error) {
      // A read-only track can still be read; it just cannot be forced.
    }

    await new Promise((resolve) => {
      let settled = false;
      const done = () => {
        if (settled) {
          return;
        }
        settled = true;
        try {
          track.removeEventListener('load', done);
        } catch (error) {
          // ignore
        }
        resolve();
      };

      try {
        track.addEventListener('load', done);
      } catch (error) {
        // ignore
      }
      setTimeout(done, 1200);
    });

    cues = cuesOf(track);
    return cues;
  }

  function matches(video) {
    return isYouTube() && Boolean(video);
  }

  // YouTube does not hand its captions to the browser as TextTracks in most
  // sessions: the player fetches them itself and paints them into
  // `.ytp-caption-window-container`. An earlier version only read
  // `video.textTracks`, so on YouTube it stayed empty even while subtitles were
  // plainly visible on screen - the extension looked broken.
  //
  // The DOM layer is therefore read as well. The text is already segmented
  // into the line being spoken; watching it gives a "live" cue that follows the
  // player. Only the current line can be captured this way, which is enough for
  // dual subtitles and for tapping a word.
  function domCaptionText() {
    const container = document.querySelector('.ytp-caption-window-container');
    if (!container) {
      return '';
    }

    // Segments are the visible pieces; joining their text keeps words intact
    // where the player splits a sentence across styled spans.
    const segments = Array.from(container.querySelectorAll('.ytp-caption-segment'))
      .map((el) => cleanText(el.textContent))
      .filter(Boolean);

    if (segments.length) {
      return segments.join(' ').replace(/\s+/g, ' ').trim();
    }

    return cleanText(container.innerText || '');
  }

  // Several players can be bound at once during a YouTube navigation (the old
  // <video> is still connected while the new one appears). Hiding the native
  // caption box is reference-counted so one adaptor's teardown does not bring
  // YouTube's captions back on top of a still-active second layer.
  let nativeHideCount = 0;

  function acquireNativeHide() {
    nativeHideCount += 1;
    try {
      document.documentElement.classList.add('dualsub-youtube-dom');
    } catch (error) {
      // Cosmetic only.
    }
  }

  function releaseNativeHide() {
    nativeHideCount = Math.max(0, nativeHideCount - 1);
    if (nativeHideCount === 0) {
      try {
        document.documentElement.classList.remove('dualsub-youtube-dom');
      } catch (error) {
        // Cosmetic only.
      }
    }
  }

  // Auto captions are repainted fragment by fragment. These constants decide
  // when the open fragment is a finished sentence:
  //   terminal punctuation  -> immediately
  //   a pause in repainting -> after IDLE
  //   a new burst of speech -> the previous fragment is closed
  //   too many words        -> hard cap so an unpunctuated monologue still moves
  // A finished sentence is held briefly after the caption box empties, so a
  // short unpunctuated line is readable instead of flashing for one tick.
  const IDLE_COMMIT_MS = 1600;
  const PAUSE_COMMIT_MS = 1200;
  const CLEAR_HOLD_MS = 900;
  const MAX_SENTENCE_WORDS = 22;

  function watchRenderedCaptions(video, ctx) {
    const builder = DS.sentenceBuilder;
    let timer = 0;
    let lastText = '';
    let lastKind = null;
    let lastStart = -Infinity;
    let lastEnd = -Infinity;
    let nativeHidden = false;

    // The sentence currently being assembled (not on screen yet).
    let buffer = '';
    let bufferStart = 0;
    let bufferKind = null;
    let lastChangeAt = 0;

    // What is actually on screen, per channel. Repainted lines can still contain
    // the already-shown sentence, so it is removed before buffering.
    const publishedByKind = {};
    let holdClearKind = null;
    let holdClearAt = 0;

    const currentTime = () => Number(video.currentTime) || 0;

    const publish = (kind, text, start) => {
      const now = currentTime();
      const from = Number.isFinite(start) && start >= 0
        ? Math.min(start, now)
        : Math.max(0, now - 0.3);
      lastStart = from;
      lastEnd = now + 3600;
      lastKind = kind;

      // Keep our own line and drop YouTube's overlapping caption box only once
      // a sentence is actually ready. Hiding it while the first sentence is
      // still being assembled would leave the viewer with no captions at all.
      if (!nativeHidden) {
        nativeHidden = true;
        acquireNativeHide();
      }
      publishedByKind[kind] = text;
      holdClearKind = null;
      holdClearAt = 0;
      ctx.emit('cues', {
        kind: kind,
        cues: [{ start: from, end: lastEnd, text: text }],
        source: 'youtube-dom',
        confidence: 'live'
      });
    };

    const clear = (kind) => {
      publishedByKind[kind] = '';
      if (lastKind === kind) {
        lastKind = null;
      }
      ctx.emit('cues', { kind: kind, cues: [], source: 'youtube-dom' });
    };

    const dropBuffer = () => {
      buffer = '';
      bufferStart = 0;
      bufferKind = null;
    };

    const commit = () => {
      if (!buffer) {
        return;
      }
      const text = buffer;
      const kind = bufferKind || EN;
      const start = bufferStart;
      dropBuffer();
      publish(kind, text, start);
    };

    const stripShown = (text, kind) => {
      const previous = publishedByKind[kind] || '';
      return previous ? builder.removePrefix(text, previous) : text;
    };

    const tick = () => {
      const text = domCaptionText();
      const at = currentTime();
      const now = Date.now();

      if (!text) {
        if (buffer) {
          const held = buffer;
          const heldKind = bufferKind || EN;
          const heldStart = bufferStart;
          dropBuffer();
          lastText = '';

          // The caption box emptied mid-sentence. What was said is more useful
          // than nothing, so a real fragment is shown and held briefly.
          if (builder.wordCount(held) >= 2) {
            publish(heldKind, held, heldStart);
            holdClearKind = heldKind;
            holdClearAt = now + CLEAR_HOLD_MS;
            return;
          }

          if (heldKind) {
            clear(heldKind);
          }
          return;
        }

        lastText = '';

        if (holdClearKind) {
          if (now < holdClearAt) {
            return;
          }
          clear(holdClearKind);
          holdClearKind = null;
          holdClearAt = 0;
          return;
        }

        if (lastKind) {
          clear(lastKind);
        }
        return;
      }

      holdClearKind = null;
      holdClearAt = 0;

      // A foreign caption (French, Spanish, ...) must not be filed into the
      // Turkish channel. That used to show untranslated foreign text under the
      // "Turkish" line. Drop it and clear the previous line instead.
      const verdict = DS.langDetect.classify('', text);
      if (verdict.confidence === 'foreign') {
        dropBuffer();
        if (lastKind) {
          clear(lastKind);
        }
        lastText = '';
        return;
      }

      const kind = verdict.lang === 'tr' ? TR : EN;

      if (text === lastText) {
        // The player still paints the same caption, but the playhead can have
        // moved outside the cue published for it (typically after seeking
        // backwards). Re-publishing re-anchors the start time; without this the
        // store had no cue at the new position and the subtitle vanished until
        // YouTube happened to change the text.
        if (buffer && now - lastChangeAt >= IDLE_COMMIT_MS) {
          commit();
          return;
        }
        if (lastKind && (at < lastStart - 0.1 || at > lastEnd - 0.5)) {
          const shown = publishedByKind[lastKind];
          if (shown) {
            publish(lastKind, shown, Math.max(0, at - 0.3));
          }
        }
        return;
      }

      const gap = lastChangeAt ? now - lastChangeAt : 0;
      lastText = text;
      lastChangeAt = now;

      if (lastKind && lastKind !== kind) {
        dropBuffer();
        clear(lastKind);
      }

      let fragment = stripShown(text, kind);
      if (!fragment) {
        return;
      }

      // Speech resumed after a pause: the sentence being assembled was not
      // punctuated, but it is over.
      if (buffer && gap >= PAUSE_COMMIT_MS && builder.wordCount(buffer) >= 2) {
        commit();
      }
      if (buffer && bufferKind && bufferKind !== kind) {
        commit();
      }

      if (!buffer) {
        buffer = fragment;
        bufferStart = Math.max(0, at - 0.25);
        bufferKind = kind;
      } else {
        buffer = builder.append(buffer, fragment);
      }

      if (builder.isTerminal(buffer) || builder.wordCount(buffer) >= MAX_SENTENCE_WORDS) {
        commit();
      }
    };

    timer = global.setInterval(tick, 250);

    return {
      detach: () => {
        global.clearInterval(timer);
        if (nativeHidden) {
          nativeHidden = false;
          releaseNativeHide();
        }
      }
    };
  }

  async function attach(video, ctx) {
    const tracks = tracksOf(video);
    if (!tracks.length) {
      // YouTube keeps the caption text in its own DOM layer; follow that. The
      // registry accepts a `live` adaptor that starts empty and emits later.
      const watcher = watchRenderedCaptions(video, ctx);
      return { en: null, tr: null, live: true, detach: watcher.detach };
    }

    const candidates = [];

    for (const track of tracks) {
      const cues = await ensureCues(track);
      if (!cues.length) {
        continue;
      }

      const kind = kindOf(track, cues);
      if (!kind) {
        continue;
      }

      candidates.push({
        track: track,
        cues: cues,
        kind: kind,
        auto: isAutoGenerated(track)
      });
    }

    const result = { en: null, tr: null };
    const listeners = [];

    for (const kind of [EN, TR]) {
      const forKind = candidates.filter((item) => item.kind === kind);
      if (!forKind.length) {
        continue;
      }

      // A manual track is worth more than an auto-generated one; if both exist,
      // keep the manual one.
      const chosen = forKind.find((item) => !item.auto) || forKind[0];
      const source = chosen.auto ? 'youtube-asr' : 'youtube';

      // Auto-generated cues are word- or phrase-sized. Rendering them as they
      // are produces the word-by-word stutter the DOM path was fixed for, so
      // they are rebuilt into sentences here as well. Human tracks are already
      // written as subtitles and are left untouched.
      let rawCount = chosen.cues.length;
      const cues = chosen.auto ? DS.sentenceBuilder.group(chosen.cues) : chosen.cues;

      result[kind] = {
        language: chosen.track.language,
        label: chosen.track.label,
        cues: cues,
        source: source
      };

      ctx.emit('cues', { kind: kind, cues: cues, source: source });

      if (ctx.getSetting('hideNativeSubtitles') !== false) {
        try {
          chosen.track.mode = 'hidden';
        } catch (error) {
          // Read-only tracks keep rendering; the overlay sits above them.
        }
      }

      const onChange = () => {
        const refreshed = cuesOf(chosen.track);
        if (refreshed.length && refreshed.length !== rawCount) {
          rawCount = refreshed.length;
          const next = chosen.auto ? DS.sentenceBuilder.group(refreshed) : refreshed;
          ctx.emit('cues', { kind: kind, cues: next, source: source });
        }
      };

      try {
        chosen.track.addEventListener('cuechange', onChange);
        listeners.push(() => chosen.track.removeEventListener('cuechange', onChange));
      } catch (error) {
        // Following future cue changes is an enhancement, not a requirement.
      }
    }

    if (!result.en && !result.tr) {
      // Tracks existed but yielded no readable text; the rendered captions may
      // still be on screen.
      const watcher = watchRenderedCaptions(video, ctx);
      return { en: null, tr: null, live: true, detach: () => {
        listeners.forEach((off) => off());
        watcher.detach();
      } };
    }

    return {
      en: result.en,
      tr: result.tr,
      detach: () => listeners.forEach((off) => off())
    };
  }

  DS.adaptorRegistry.register({
    id: 'youtube',
    priority: 70,
    matches: matches,
    attach: attach,
    detach: () => {}
  });

  DS.adaptors = DS.adaptors || {};
  DS.adaptors.youtube = {
    isYouTube: isYouTube,
    cleanText: cleanText,
    cuesOf: cuesOf,
    kindOf: kindOf,
    isAutoGenerated: isAutoGenerated,
    tracksOf: tracksOf
  };
})(typeof self !== 'undefined' ? self : this);
